questionvariables.text:
/*Question variables*/
aa:rand_with_prohib(-5,5,[0]);
bb:rand_with_prohib(-5,5,[0]);
cc:rand_with_prohib(-5,5,[0]);
dd:rand_with_prohib(-5,5,[0]);

func_w:expand((aa*x-z)*(x+bb*z))/y^(cc);
func_x:t^(dd)+cc;
func_y:cos(bb*t);
func_z:dd*t;

/*Worked solution*/
func1a:diff(func_w,x);  func1b:diff(func_x,t);
func2a:diff(func_w,y);  func2b:diff(func_y,t);
func3a:diff(func_w,z);  func3b:diff(func_z,t);
ta1:func1a*func1b+func2a*func2b+func3a*func3b;
ta:ratsimp(ta1);

feedbackvariables.text:
/*mistake1:Computing the partial derivative of w wrt to t only and forgoing the other derivatives */
mistake1:diff(func_w,t);

/*mistake2:Computing all the derivatives of all the three functions wrt to t only then adding the final result. */
mistake2:diff(func_w,t)+diff(func_x,t)+diff(func_y,t)+diff(func_z,t);
